    liabilities_fv: Annotated[Optional[float], Field(description='Fair value of assumed liabilities, in currency units.')] = None,
    asset_type: Annotated[Optional[str], Field(description='Asset type, e.g. "patent", "trademark", "software", "customer_list".')] = None,
