@mcp.tool(
    name='valuation_simulation',
    title='Uncertainty & Sensitivity',
    description='Uncertainty analysis: Monte Carlo valuation, Monte Carlo sensitivity ranking, decision-tree expected values, and one-at-a-time sensitivity analysis. Method selects the formula. Use to quantify and stress the uncertainty around a point valuation; monte_carlo simulates all listed inputs, monte_carlo_sensitivity ranks the drivers. For a single deterministic point value use the relevant valuation tool; sensitivity_analysis varies one parameter of a core function only. Parameters apply per method: monte_carlo needs input_distributions (optional: iterations, seed); monte_carlo_sensitivity needs base_params + distributions (optional: iterations, seed); decision_tree needs tree; sensitivity_analysis needs function_name + parameter_name + parameter_range + fixed_parameters. monte_carlo_sensitivity requires iterations between 1000 and 100000. Only method is required; every other parameter is method-dependent, so supply just the ones named for the selected method and leave the rest unset. Deterministic and side-effect-free: identical inputs always return an identical value. Supplying an unknown method, or leaving unset a parameter that the chosen method requires, returns an error instead of a value.',
    output_schema=OUTPUT_SCHEMA,
    annotations=COMMON_ANNOTATIONS,
    tags={'monte-carlo', 'sensitivity', 'decision-tree', 'uncertainty'},
)
def valuation_simulation(
    method: Annotated[Literal['monte_carlo', 'monte_carlo_sensitivity', 'decision_tree', 'sensitivity_analysis'], Field(description='Formula to apply. Options: monte_carlo = Simulate all listed inputs, sum-based valuation.; monte_carlo_sensitivity = Rank parameters by their impact on the valuation.; decision_tree = Backward induction over a decision tree.; sensitivity_analysis = One-at-a-time sensitivity of a core function.')],
    input_distributions: Annotated[Optional[list[dict]], Field(description='Inputs to simulate, each {name, distribution, params}; distribution is normal (mean, std), uniform (low, high) or triangular (low, high, mode).')] = None,
    iterations: Annotated[Optional[int], Field(description='Simulation iterations; monte_carlo_sensitivity requires 1000-100000.')] = None,
    seed: Annotated[Optional[int], Field(description='Random seed for reproducible simulations.')] = None,
    base_params: Annotated[Optional[dict], Field(description='Base values for all parameters, including those held fixed.')] = None,
    distributions: Annotated[Optional[dict], Field(description='Map of parameter name to {distribution, params} for the simulated inputs.')] = None,
    tree: Annotated[Optional[dict], Field(description='Decision tree {"nodes": [...], "edges": [...]}; node types decision, chance, terminal.')] = None,
    function_name: Annotated[Optional[str], Field(description='Core function to vary, e.g. "present_value", "capm_discount_rate", "wacc".')] = None,
    parameter_name: Annotated[Optional[str], Field(description='Name of the parameter to vary.')] = None,
    parameter_range: Annotated[Optional[list[float]], Field(description='Values to test for the varied parameter.')] = None,
    fixed_parameters: Annotated[Optional[dict], Field(description='Values for all other parameters, held constant.')] = None,
) -> dict:
    """Uncertainty analysis: Monte Carlo valuation, Monte Carlo sensitivity ranking, decision-tree expected values, and one-at-a-time sensitivity analysis."""
    return call_tool('valuation_simulation', {'method': method, 'input_distributions': input_distributions, 'iterations': iterations, 'seed': seed, 'base_params': base_params, 'distributions': distributions, 'tree': tree, 'function_name': function_name, 'parameter_name': parameter_name, 'parameter_range': parameter_range, 'fixed_parameters': fixed_parameters})

